/**
 * Exo covariance driver: mirrors PolyBench/C covariance.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* Include the Exo-generated kernel header. */
#include "generated/covariance/covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # imported for potential scheduling directives
from exo.libs.memories import DRAM

@proc
def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # -------------------------------------------------------------------------
    # Optimized covariance kernel
    #
    # Differences from the naive version:
    #   - Precompute reciprocals of float_n and (float_n - 1.0) once, turning
    #     inner-loop divisions into cheaper multiplications.
    #   - Compute column means in row-major order to respect the layout of
    #     'data' and improve cache efficiency.
    #   - Fuse centering of 'data' with the covariance accumulation so that
    #     each row is read, centered, and used exactly once.
    #   - Use a temporary row buffer x_row of length m (O(m) extra memory),
    #     which is negligible compared to the O(n*m + m*m) main arrays.
    #
    # The final results match the original kernel:
    #   - 'mean[j]' holds the per-column mean.
    #   - 'data[i, j]' is centered in-place.
    #   - 'cov' is the symmetric sample covariance matrix.
    # -------------------------------------------------------------------------

    # Precompute reciprocals to avoid repeated divisions inside loops.
    inv_float_n: DATA_TYPE
    inv_float_n_minus_1: DATA_TYPE
    inv_float_n = 1.0 / float_n
    inv_float_n_minus_1 = 1.0 / (float_n - 1.0)

    # -------------------------------------------------------------------------
    # Phase 1: compute column means
    #   mean[j] = (1 / float_n) * sum_{i=0}^{n-1} data[i, j]
    # We first zero 'mean', then accumulate in row-major order for better
    # locality on 'data', and finally scale by inv_float_n.
    # -------------------------------------------------------------------------
    for j in seq(0, m):
        mean[j] = 0.0

    # Accumulate column sums with 'i' outer, 'j' inner:
    # this walks 'data' row by row (contiguous in 'j').
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # Scale by 1 / n.
    for j in seq(0, m):
        mean[j] = mean[j] * inv_float_n

    # -------------------------------------------------------------------------
    # Phase 2: initialize covariance matrix (upper triangle)
    #
    # We only touch cov[i, j] for j >= i here; the lower triangle is filled
    # from the upper triangle after the accumulation phase.
    # -------------------------------------------------------------------------
    for i_feat in seq(0, m):
        for j_feat in seq(i_feat, m):
            cov[i_feat, j_feat] = 0.0

    # Temporary buffer for one centered row. This adds only O(m) extra
    # memory beyond 'data', 'cov', and 'mean'.
    x_row: DATA_TYPE[m] @ DRAM

    # -------------------------------------------------------------------------
    # Phase 3: fuse centering and covariance accumulation
    #
    # For each row r:
    #   - center it into x_row:
    #       x_row[j] = data[r, j] - mean[j]
    #       data[r, j] = x_row[j]    # preserve side-effect on 'data'
    #   - apply a rank-1 update to the upper triangle:
    #       cov[i, j] += x_row[i] * x_row[j],  for 0 <= i <= j < m
    #
    # Mathematically:
    #   cov[i, j] = sum_{r=0}^{n-1} (data[r, i] - mean[i]) *
    #                           (data[r, j] - mean[j])
    # which matches the original three-nested-loop computation up to
    # reordering of the summation.
    # -------------------------------------------------------------------------
    for r in seq(0, n):
        # Center the current row and write it back into 'data'.
        for j in seq(0, m):
            x_row[j] = data[r, j] - mean[j]
            data[r, j] = x_row[j]

        # Rank-1 update of the upper triangle: cov += x_row^T * x_row.
        for i_feat in seq(0, m):
            xi: DATA_TYPE
            xi = x_row[i_feat]
            for j_feat in seq(i_feat, m):
                cov[i_feat, j_feat] += xi * x_row[j_feat]

    # -------------------------------------------------------------------------
    # Phase 4: normalize by (n - 1) and enforce symmetry
    #
    # The original kernel divides each cov[i, j] by (float_n - 1.0) and
    # then sets cov[j, i] = cov[i, j]. We do the same here, but we apply
    # the scaling with a precomputed reciprocal.
    # -------------------------------------------------------------------------
    for i_feat in seq(0, m):
        for j_feat in seq(i_feat, m):
            cov[i_feat, j_feat] = cov[i_feat, j_feat] * inv_float_n_minus_1
            cov[j_feat, i_feat] = cov[i_feat, j_feat]
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_covariance (/*ctxt=*/NULL, m, n,
                     (DATA_TYPE*)&float_n,
                     (DATA_TYPE*)POLYBENCH_ARRAY(data),
                     (DATA_TYPE*)POLYBENCH_ARRAY(cov),
                     (DATA_TYPE*)POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}

