/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *   # imported as requested (not used directly here)
from exo.libs.memories import DRAM

# Tile size for the feature (column) dimension in the covariance phase.
# This is a tunable parameter; 32 works well on typical x64 with L1/L2 caches.
TILE_M = 32

@proc
def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # Basic sanity for the problem dimensions.
    assert m > 0
    assert n > 0

    # Precompute reciprocals once to avoid repeated divisions in loops.
    # This preserves the mathematical result while replacing many divides
    # with cheaper multiplies.
    inv_float_n: DATA_TYPE
    inv_float_n_minus1: DATA_TYPE
    inv_float_n = 1.0 / float_n
    inv_float_n_minus1 = 1.0 / (float_n - 1.0)

    # ----------------------------------------------------------------------
    # 1. Compute per-column means:
    #       mean[j] = (1 / n) * sum_{i=0}^{n-1} data[i, j]
    #
    # We traverse data row-major (i outer, j inner) to match the storage
    # layout data[n, m], which is row-major in C. This differs in loop
    # order from the original column-wise loop, but is algebraically
    # equivalent:
    #   original:
    #     for j: mean[j] = (1/n) * sum_i data[i, j]
    #   here:
    #     mean[j] = 0;
    #     for i: for j: mean[j] += data[i, j];
    #     for j: mean[j] *= (1/n)
    # ----------------------------------------------------------------------

    # Initialize means to zero.
    for j in seq(0, m):
        mean[j] = 0.0

    # Accumulate column sums row by row (good spatial locality on data).
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # Normalize by n using the precomputed reciprocal.
    for j in seq(0, m):
        mean[j] = mean[j] * inv_float_n

    # ----------------------------------------------------------------------
    # 2. Center the data in-place:
    #       data[i, j] <- data[i, j] - mean[j]
    #
    # After this loop, 'data' holds the centered samples X. This matches
    # the original kernel’s second loop nest exactly, but still uses a
    # row-major iteration order (i outer, j inner).
    # ----------------------------------------------------------------------
    for i in seq(0, n):
        for j in seq(0, m):
            data[i, j] = data[i, j] - mean[j]

    # ----------------------------------------------------------------------
    # 3. Compute the unscaled covariance as a sequence of rank-1 updates:
    #
    #   Let X be the centered data matrix (n×m). The sample covariance is
    #       cov = (1 / (n - 1)) * X^T X
    #
    #   We compute:
    #       cov[i, j] = sum_{r=0}^{n-1} X[r, i] * X[r, j],  for j >= i
    #
    #   using a row-wise outer-product scheme:
    #       for each row r:
    #           x_row[:] = X[r, :]
    #           cov += x_row^T * x_row   (upper triangle only)
    #
    #   This preserves the mathematical result but changes the summation
    #   order compared to the original triple loop over (i, j, k). It
    #   greatly improves data locality:
    #     - each centered row is loaded once in a contiguous pass,
    #     - then reused from a small temporary buffer for O(m^2) updates.
    #
    #   We also block the (i, j) feature dimensions into TILE_M×TILE_M
    #   tiles so that a tile of cov stays in cache while processing all
    #   rows. No extra large buffers are allocated; only an O(m) scratch
    #   buffer x_row is used.
    # ----------------------------------------------------------------------

    # Scratch buffer for one centered row. Adds only O(m) extra memory.
    x_row: DATA_TYPE[m]

    # Initialize full covariance matrix to zero. We later compute only the
    # upper triangle (j >= i) and then make the matrix symmetric.
    for i in seq(0, m):
        for j in seq(0, m):
            cov[i, j] = 0.0

    # For each centered row r, form a rank-1 update of cov.
    for r in seq(0, n):
        # Load one full centered row into a contiguous temporary buffer.
        for j in seq(0, m):
            x_row[j] = data[r, j]

        # Blocked outer-product update: cov += x_row^T * x_row (upper triangle).
        # We tile both feature indices i and j into TILE_M×TILE_M tiles and
        # process only tiles in the upper triangle (J >= I). Inside each tile,
        # we update only entries with j_index >= i_index.
        for I in seq(0, (m + TILE_M - 1) // TILE_M):
            for J in seq(I, (m + TILE_M - 1) // TILE_M):
                for ii in seq(0, TILE_M):
                    for jj in seq(0, TILE_M):
                        # Compute the actual feature indices within this tile.
                        # Edge tiles (where m is not divisible by TILE_M) are
                        # handled via explicit bounds checks.
                        if (
                            I * TILE_M + ii < m
                            and J * TILE_M + jj < m
                            and (J * TILE_M + jj) >= (I * TILE_M + ii)
                        ):
                            cov[I * TILE_M + ii, J * TILE_M + jj] += (
                                x_row[I * TILE_M + ii]
                                * x_row[J * TILE_M + jj]
                            )

    # ----------------------------------------------------------------------
    # 4. Scale by 1 / (n - 1) and enforce symmetry:
    #
    #   cov[i, j] = (1 / (n - 1)) * sum_r X[r, i] * X[r, j]
    #   for all i, j, with the matrix symmetric (cov[j, i] = cov[i, j]).
    #
    #   At this point, the upper triangle (including the diagonal) holds
    #   the unscaled sums. We multiply each by inv_float_n_minus1 and
    #   copy to the lower triangle.
    # ----------------------------------------------------------------------
    for i in seq(0, m):
        for j in seq(i, m):
            cov[i, j] = cov[i, j] * inv_float_n_minus1
            cov[j, i] = cov[i, j]
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_covariance (/*ctxt=*/NULL, m, n,
                     (DATA_TYPE*)&float_n,
                     (DATA_TYPE*)POLYBENCH_ARRAY(data),
                     (DATA_TYPE*)POLYBENCH_ARRAY(cov),
                     (DATA_TYPE*)POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
